package towerdefence.game.interfaces;

import towerdefence.game.input.InputCommand;

import java.util.List;

/**
 * where input comes from
 */
public interface InputSource {
    /**
     * Polls the input source for any new commands generated by user interactions since the last poll.
     *
     * @return a list of InputCommand objects representing the commands generated by user interactions since the last poll. If no new commands have been generated, this method may return an empty list.
     */
    List<InputCommand> pollCommands();

    /**
     * Installs necessary event handlers for the input source.
     * This is called after the game view is created, allowing the input source to attach listeners to the view's components if needed.
     */
    default void installHandlers() {
    }

}
